/** نوع‌نوشته‌های عمومی، برای فهرست‌های انتخابی (بدون پیوست) */
function mb_post_type_options_noattach() {
    $o = mb_post_type_options();
    unset($o['attachment']);
    return $o;
}
/** فهرست بلوک‌های گوتنبرگ که روی سایت ثبت شده‌اند (پویا؛ با نصب افزونه‌ی جدید خودکار بزرگ‌تر می‌شود) */
function mb_block_options() {
    $out = [];
    if (class_exists('WP_Block_Type_Registry')) {
        foreach (WP_Block_Type_Registry::get_instance()->get_all_registered() as $name => $b) {
            $t = !empty($b->title) ? $b->title : $name;
            $out[$name] = $t . ' · ' . $name;
        }
    }
    asort($out);
    return $out;
}
function mb_checkout_field_options() {
    return [
        'billing_company' => 'نام شرکت', 'billing_address_2' => 'آدرس خط دوم', 'billing_postcode' => 'کد پستی', 'billing_state' => 'استان',
        'billing_city' => 'شهر', 'billing_phone' => 'تلفن', 'shipping_company' => 'نام شرکت (ارسال)', 'shipping_address_2' => 'آدرس خط دوم (ارسال)',
        'shipping_postcode' => 'کد پستی (ارسال)', 'order_comments' => 'توضیحات سفارش',
    ];
}

