/** ادغام منوها و تغییرات ساختاری بعد از ساخت فهرست امکان‌ها */
function mb_patch_features2(&$f) {
    $widgets = ['wc_status_widget', 'wc_setup_widget', 'elementor_widget', 'yoast_widget', 'wpdesk_widgets', 'dashboard_widgets'];
    foreach ($f as &$x) {
        if (in_array($x['cat'], ['visitor', 'updates'], true)) $x['cat'] = 'admin';
        if (in_array($x['id'], $widgets, true)) { $x['cat'] = 'admin'; $x['section'] = 'ویجت‌های صفحه‌ی اصلی پیشخوان'; }
        switch ($x['id']) {
            case 'admin_notices':
                $x['section'] = 'اعلان‌ها'; $x['wide'] = true; $x['last'] = true; break;
            case 'unregister_tags':
                $x['title'] = 'غیرفعال‌سازی برچسب نوشته‌ها (وردپرس)';
                $x['tip'] = 'برچسب‌های نوشته (Tags) و منوی آن‌ها حذف می‌شود؛ مناسب سایت‌هایی که فقط دسته‌بندی دارند.'; break;
            case 'hide_admin_bar':
                $x['type'] = 'select'; $x['default'] = 'off'; unset($x['rec']);
                $x['options'] = ['off' => 'نمایش عادی', 'non_admin' => 'مخفی برای غیرمدیران', 'all' => 'مخفی برای همه (حتی مدیران)'];
                $x['title'] = 'مخفی‌کردن نوار بالای سایت';
                $x['tip'] = 'نوار مدیریتِ بالای سایت را برای غیرمدیران یا برای همه (حتی مدیران) پنهان می‌کند.'; break;
            case 'spam_cleaner':
                $x['type'] = 'toggle'; unset($x['options']); $x['default'] = 0;
                $x['tip'] = 'دیدگاه‌های اسپم که بیشتر از تعداد روزِ انتخابی در پوشه‌ی اسپم مانده‌اند خودکار برای همیشه حذف می‌شوند.';
                $x['fields'] = [['id' => 'spam_cleaner_days', 'type' => 'number', 'default' => 7, 'min' => 1, 'max' => 365, 'step' => 1, 'unit' => 'روز نگه‌داری']]; break;
            case 'gravatar':
                $x['fields'] = [['id' => 'gravatar_url', 'type' => 'image', 'default' => '', 'placeholder' => 'انتخاب تصویر جایگزین از رسانه‌ها (اختیاری)']]; break;
            case 'heartbeat':
                $x['tip'] = 'Heartbeat هر چند ثانیه با سرور ارتباط می‌گیرد (برای ذخیره‌ی خودکار، قفل نوشته و اعلان‌ها). در حالت «کم‌کردن درخواست‌ها» و «فقط در صفحه‌ی ویرایش» می‌توانید فاصله‌ی زمانی را هم تعیین کنید. اگر «غیرفعال» را انتخاب کنید، ذخیره‌ی خودکار و قفل نوشته هم کار نمی‌کند.';
                foreach ($x['fields'] as &$fl) { if ($fl['id'] === 'heartbeat_freq') { $fl['show_if'] = ['heartbeat', ['slow', 'editor']]; } } unset($fl); break;
            case 'sec_rest_access':
                $x['title'] = 'غیرفعال‌سازی REST API';
                $x['default'] = 'everyone';
                $x['options'] = ['everyone' => 'پیش‌فرض (فعال)', 'admins' => 'غیرفعال برای غیر-مدیران', 'logged_in' => 'غیرفعال برای کاربران خارج شده'];
                $x['tip'] = 'REST API راهی است که برنامه‌ها، ویرایشگر بلوک و افزونه‌ها از طریق آدرس /wp-json داده‌ی سایت را می‌خوانند و تغییر می‌دهند. می‌توانید دسترسی را فقط برای مدیران یا فقط برای کاربران واردشده نگه دارید. فرم‌های Contact Form 7 و فروشگاه ووکامرس مستثنا هستند.'; break;
            case 'net_learn':
                $x['tip'] = 'افزونه هنگام بازدیدهای عادی (و درخواست‌های خود سایت به سرویس‌های بیرونی) دامنه‌های خارجی را شناسایی و در «پیشنهادها» ذخیره می‌کند. نیازی به اسکن دستی نیست و فشاری به سرور نمی‌آورد.'; break;
        }
        // امکان‌هایی که چند فیلد دارند، تک‌ستونه‌اند
        if (!empty($x['fields']) && count($x['fields']) >= 2) $x['wide'] = true;
    }
}
